def verify_peer_message(raw: bytes, sig_hex: str, ts: int) -> dict:
    if abs(time.time() - ts) > 60:
        raise ValueError("stale")
    key = os.environ["AGENT_BUS_HMAC_KEY"].encode()
    expected = hmac.new(key, str(ts).encode() + b"." + raw, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, sig_hex):
        raise PermissionError("bad signature")
    return json.loads(raw)

