def parse_numbers(llm, text: str) -> list[float]:
    raw = llm.invoke(f"Return a Python list literal of the numbers in: {text}", max_tokens=100).content
    values = ast.literal_eval(raw.strip())
    if not isinstance(values, list) or not all(isinstance(v, (int, float)) for v in values):
        raise ValueError("bad output")
    return values
